function renderMiniBoard(){const mini=document.getElementById('miniBoard');if(!mini)return;const board=['r','n','b','q','k','b','n','r','p','p','p','p','p','p','p','p',...Array(32).fill(''), 'P','P','P','P','P','P','P','P','R','N','B','Q','K','B','N','R'];mini.innerHTML='';for(const code of board){if(code){const cell=document.createElement('span');cell.className='mini-piece';cell.innerHTML=pieceImgHtml(code);mini.appendChild(cell)}else mini.appendChild(document.createElement('i'));}}
