// ---------------- Chess engine ----------------
function emptyPos(){return{board:Array(64).fill(null),turn:'w',castling:'KQkq',ep:-1,halfmove:0,fullmove:1}}
function startFen(){return'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1'}
