function opposite(c){return c==='w'?'b':'w'}
function onBoard(r,c){return r>=0&&r<8&&c>=0&&c<8}
function rc(i){return[Math.floor(i/8),i%8]}
function parseFen(fen){const [bp,turn='w',cast='-',ep='-',half='0',full='1']=String(fen||startFen()).split(' '),board=[];for(const row of bp.split('/')){for(const ch of row){if(/\d/.test(ch))for(let n=0;n<Number(ch);n++)board.push(null);else board.push(ch)}}while(board.length<64)board.push(null);return{board:board.slice(0,64),turn,castling:cast==='-'?'':cast,ep:ep==='-'?-1:squareIndex(ep),halfmove:Number(half)||0,fullmove:Number(full)||1}}
