function renderLobby(room){els.lobbyRoomCode.textContent=state.roomCode;els.lobbyPlayers.innerHTML=playerIds(room).map(uid=>{const p=room.players?.[uid]||{};return`<div class="lobby-player"><span class="ava">${p.avatar||'😎'}</span><div><b>${escapeHtml(p.name||'لاعب')}</b><small>${uid===room.hostUid?'منشئ الغرفة':'اللاعب الثاني'}</small></div><span>${p.connected!==false?'🟢':'⚪'}</span></div>`}).join('');els.lobbyStatus.textContent=room.guestUid?'اللاعبان جاهزان — جاري بدء المباراة…':'في انتظار اللاعب الثاني…'}

async function submitMove(move){if(state.reviewFen)return;const now=nowMs();const moveMeta={sound:'move'};const result=await runTransaction(roomRef(),room=>{if(!room||room.status!=='playing'||!room.game)return;const g=room.game,pos=parseFen(g.fen),myColor=g.colors?.white===state.uid?'w':g.colors?.black===state.uid?'b':null;if(!myColor||pos.turn!==myColor)return;const all=legalMoves(pos,myColor),legal=all.find(m=>m.from===move.from&&m.to===move.to&&(m.promotion||null)===(move.promotion||null));if(!legal)return;const time=Number(room.settings?.timeControl)||0;if(time>0){const elapsed=Math.max(0,now-Number(g.turnStartedAt||now)),left=Math.max(0,Number(g.clocks?.[myColor]??time)-elapsed);g.clocks=g.clocks||{w:time,b:time};g.clocks[myColor]=left;if(left<=0){g.result={type:'timeout',winner:opposite(myColor),text:'انتهى الوقت'};room.status='finished';return room}}
 const san=sanForMove(pos,legal,all),next=makeMove(pos,legal),fen=toFen(next),keys=[...(g.positionHistory||[]),positionKey(next)],hist=[...(g.history||[]),{from:legal.from,to:legal.to,piece:legal.piece,capture:legal.capture||null,promotion:legal.promotion||null,san,fenAfter:fen,by:state.uid,at:now}];g.fen=fen;g.history=hist;g.positionHistory=keys;g.lastMove={from:legal.from,to:legal.to,san,by:state.uid,at:now};g.turnStartedAt=now;room.drawOffer=null;const outcome=gameOutcome(next,keys);if(outcome){g.result=outcome;room.status='finished'}room.expiresAt=now+7*86400000;moveMeta.sound=legal.castle?'castle':(legal.capture||legal.ep)?'capture':inCheck(next,next.turn)?'check':'move';return room});if(result.committed){state.selectedSquare=null;state.legalMoves=[];state.reviewFen=null;playSound(moveMeta.sound)}}
