// ---------------- Rendering & interaction ----------------
function playerCardHtml(p,color,turn){return`<span class="ava">${p?.avatar||'😎'}</span><div><b>${escapeHtml(p?.name||'لاعب')}</b><small>${color==='w'?'الأبيض':'الأسود'}${turn?' • دوره الآن':''}</small></div>`}
function renderGame(room){const g=room.game||{},pos=parseFen(state.reviewFen||g.fen),myColor=playerColor(room),opp=otherUid(room),oppColor=myColor?opposite(myColor):null,my=room.players?.[state.uid],op=room.players?.[opp];els.roomCodeLabel.textContent=state.roomCode;els.myInfo.innerHTML=playerCardHtml(my,myColor,room.status==='playing'&&parseFen(g.fen).turn===myColor);els.opponentInfo.innerHTML=playerCardHtml(op,oppColor,room.status==='playing'&&parseFen(g.fen).turn===oppColor);els.myInfo.classList.toggle('turn',room.status==='playing'&&parseFen(g.fen).turn===myColor);els.opponentInfo.classList.toggle('turn',room.status==='playing'&&parseFen(g.fen).turn===oppColor);renderBoard(pos,myColor,g);renderMoves(room);renderCaptured(room,myColor);renderPromotionChoices(myColor||'w');renderClocks(room);renderDrawOffer(room);renderChat(room);renderVoiceUi();if(room.reaction&&room.reaction.at>state.lastReactionAt){state.lastReactionAt=room.reaction.at;if(room.reaction.by!==state.uid)toast(room.reaction.emoji)};
 const live=parseFen(g.fen),check=inCheck(live,live.turn),myTurn=live.turn===myColor;els.statusBanner.classList.toggle('check',check&&room.status==='playing');els.statusBanner.textContent=room.status==='finished'?'انتهت المباراة':state.reviewFen?'أنت تشاهد نقلة سابقة — اضغط «الحالي» للعودة':check?(myTurn?'كش عليك!':'كش على صاحبك!'):myTurn?'دورك الآن':'دور صاحبك';els.offerDrawBtn.disabled=room.status!=='playing';els.resignBtn.disabled=room.status!=='playing';if(room.status==='finished')showResult(room);else els.resultModal.classList.add('hidden')}
function renderBoard(pos,myColor,g){els.chessBoard.innerHTML='';const orientation=myColor||'w',order=orientation==='w'?[...Array(64).keys()]:[...Array(64).keys()].reverse(),liveFen=state.room?.game?.fen,last=g?.lastMove;const livePos=parseFen(liveFen);const checkSq=inCheck(pos,pos.turn)?kingSquare(pos,pos.turn):-1;for(const i of order){const [r,c]=rc(i),sq=document.createElement('div');sq.className=`square ${(r+c)%2?'dark':'light'}`;sq.dataset.index=i;if(last&&(i===last.from||i===last.to)&&!state.reviewFen)sq.classList.add('last');if(i===state.selectedSquare&&!state.reviewFen)sq.classList.add('selected');const legal=state.legalMoves.filter(m=>m.to===i);if(legal.length&&!state.reviewFen){sq.classList.add('legal');if(pos.board[i]||legal.some(m=>m.ep))sq.classList.add('capture')}if(i===checkSq)sq.classList.add('check');const p=pos.board[i];if(p){const piece=document.createElement('span');piece.className=`piece ${pieceColor(p)==='w'?'white':'black'}`;piece.innerHTML=pieceImgHtml(p);piece.dataset.index=i;if(!state.reviewFen&&state.room?.status==='playing'&&pieceColor(p)===myColor&&livePos.turn===myColor)piece.classList.add('draggable');sq.appendChild(piece)}const file=orientation==='w'?r===7:r===0,rank=orientation==='w'?c===0:c===7;if(file){const x=document.createElement('span');x.className='coord file';x.textContent=String.fromCharCode(97+c);sq.appendChild(x)}if(rank){const x=document.createElement('span');x.className='coord rank';x.textContent=String(8-r);sq.appendChild(x)}els.chessBoard.appendChild(sq)}}
function renderMoves(room){const h=room.game?.history||[];els.moveCount.textContent=`${h.length} نقلة`;els.movesList.innerHTML='';for(let i=0;i<h.length;i+=2){const no=document.createElement('span');no.className='move-no';no.textContent=`${i/2+1}.`;els.movesList.appendChild(no);for(let k=0;k<2;k++){const m=h[i+k],b=document.createElement('button');b.className='move-btn';if(m){b.textContent=m.san;b.title=squareName(m.from)+'-'+squareName(m.to);b.addEventListener('click',()=>{state.reviewFen=m.fenAfter;state.selectedSquare=null;state.legalMoves=[];renderGame(state.room)})}else b.disabled=true;els.movesList.appendChild(b)}}els.livePositionBtn.classList.toggle('hidden',!state.reviewFen)}
