function renderClocks(room){const myColor=playerColor(room),opColor=myColor?opposite(myColor):'b',pos=parseFen(room.game.fen),my=remainingClock(room,myColor),op=remainingClock(room,opColor);els.myClock.textContent=clockText(my);els.opponentClock.textContent=clockText(op);for(const [el,val] of [[els.myClock,my],[els.opponentClock,op]]){el.classList.toggle('low',val!=null&&val<=60000&&val>10000);el.classList.toggle('critical',val!=null&&val<=10000)}els.myClock.classList.toggle('active',room.status==='playing'&&pos.turn===myColor);els.opponentClock.classList.toggle('active',room.status==='playing'&&pos.turn===opColor);if(room.status==='playing'&&Number(room.settings?.timeControl)&&remainingClock(room,pos.turn)<=0)claimTimeout().catch(console.warn)}
