function startDrag(e,piece){if(state.reviewFen||!state.room||state.room.status!=='playing')return;const from=Number(piece.dataset.index),pos=parseFen(state.room.game.fen),myColor=playerColor(state.room);if(pos.turn!==myColor||pieceColor(pos.board[from])!==myColor)return;const moves=legalMoves(pos,myColor).filter(m=>m.from===from);if(!moves.length)return;state.selectedSquare=from;state.legalMoves=moves;renderGame(state.room);const ghost=document.createElement('div');ghost.className=`drag-piece ${myColor==='w'?'white':'black'}`;ghost.innerHTML=pieceImgHtml(pos.board[from],'drag-svg');document.body.appendChild(ghost);piece.classList.add('drag-source');state.drag={from,moves,ghost,pointerId:e.pointerId};positionGhost(e);try{piece.setPointerCapture(e.pointerId)}catch{}e.preventDefault()}
