function chatItems(room){return Object.values(room.chat||{}).filter(Boolean).sort((a,b)=>(a.at||0)-(b.at||0)).slice(-80)}
function renderChat(room){const items=chatItems(room);if(items.length>state.lastChatCount&&!els.chatPanel.classList.contains('hidden')){}else if(items.length>state.lastChatCount){els.chatUnread.textContent=Math.min(9,items.length-state.lastChatCount);els.chatUnread.classList.remove('hidden')}state.lastChatCount=items.length;els.chatMessages.innerHTML=items.map(m=>`<div class="chat-msg ${m.uid===state.uid?'mine':'theirs'}"><small>${m.uid===state.uid?'أنت':escapeHtml(m.name||'صاحبك')}</small>${escapeHtml(m.text||'')}</div>`).join('')||'<div class="chat-msg theirs">ابدأوا الكلام 👋</div>';if(!els.chatPanel.classList.contains('hidden'))requestAnimationFrame(()=>els.chatMessages.scrollTop=els.chatMessages.scrollHeight)}
