// ---------------- Voice ----------------
const DEFAULT_ICE=[{urls:['stun:stun.l.google.com:19302','stun:stun1.l.google.com:19302']}];let rtcConfig=null;
async function getRtcConfig(){if(rtcConfig)return rtcConfig;const extra=Array.isArray(turnConfig?.iceServers)?turnConfig.iceServers:[];rtcConfig={iceServers:[...DEFAULT_ICE,...extra],iceCandidatePoolSize:1,iceTransportPolicy:'all'};return rtcConfig}
function voiceCallRef(){return ref(db,`rooms/${state.roomCode}/voiceCall`)}function candRef(uid,key){return ref(db,`rooms/${state.roomCode}/voiceCall/candidates/${uid}/${key}`)}
async function ensureMic(){if(state.localStream)return state.localStream;state.localStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});return state.localStream}
function serDesc(d){return{type:d.type,sdp:d.sdp}}function serCand(c){return{candidate:c.candidate,sdpMid:c.sdpMid,sdpMLineIndex:c.sdpMLineIndex,usernameFragment:c.usernameFragment||null}}
async function writeCand(c){const key=`${Date.now()}_${Math.random().toString(36).slice(2,7)}`;await set(candRef(state.uid,key),serCand(c))}
async function flushIce(){if(!state.voiceSignalReady)return;const q=[...state.pendingIce];state.pendingIce=[];for(const c of q)await writeCand(c).catch(console.warn)}
async function createPeer(){try{state.peer?.close()}catch{}state.seenIce=new Set();state.remoteDescriptionSet=false;state.pendingIce=[];state.voiceSignalReady=false;const pc=new RTCPeerConnection(await getRtcConfig());state.peer=pc;const stream=await ensureMic();stream.getTracks().forEach(t=>pc.addTrack(t,stream));state.remoteStream=new MediaStream();els.remoteAudio.srcObject=state.remoteStream;pc.ontrack=e=>{for(const t of(e.streams?.[0]?.getTracks()||[e.track]))if(!state.remoteStream.getTracks().some(x=>x.id===t.id))state.remoteStream.addTrack(t);els.remoteAudio.play().catch(()=>{})};pc.onicecandidate=e=>{if(!e.candidate)return;state.voiceSignalReady?writeCand(e.candidate).catch(console.warn):state.pendingIce.push(e.candidate)};pc.onconnectionstatechange=()=>{const s=pc.connectionState;els.voiceStatusText.textContent=s==='connected'?'متصل صوتيًا ✅':s==='connecting'?'جاري توصيل الصوت…':s==='disconnected'?'انقطع الصوت مؤقتًا…':s==='failed'?'تعذر الاتصال الصوتي':'اتصال صوتي';if(s==='failed')toast('تعذر الاتصال الصوتي. جرّب الاتصال مرة أخرى.')};return pc}
async function addRemoteCandidates(call){if(!state.peer||!call?.candidates)return;const remote=state.uid===call.callerUid?call.calleeUid:call.callerUid;for(const[key,c]of Object.entries(call.candidates?.[remote]||{})){if(state.seenIce.has(key))continue;try{await state.peer.addIceCandidate(new RTCIceCandidate(c));state.seenIce.add(key)}catch(e){console.warn(e)}}}
async function startVoice(){if(state.currentCallId)return;const callee=otherUid();if(!callee){toast('استنى صاحبك يدخل الأول.');return}try{const id=`${Date.now()}_${state.uid.slice(0,5)}`;state.currentCallId=id;const pc=await createPeer(),offer=await pc.createOffer({offerToReceiveAudio:true});await pc.setLocalDescription(offer);await set(voiceCallRef(),{id,callerUid:state.uid,calleeUid:callee,status:'ringing',offer:serDesc(pc.localDescription),createdAt:nowMs()});state.voiceSignalReady=true;await flushIce();renderVoiceUi()}catch(e){console.error(e);cleanupVoice();toast(e.name==='NotAllowedError'?'اسمح باستخدام الميكروفون.':'تعذر بدء المكالمة.') }}
async function acceptVoice(){const call=state.incomingCall;if(!call||state.processingVoice)return;state.processingVoice=true;try{els.voiceIncomingModal.classList.add('hidden');state.currentCallId=call.id;const pc=await createPeer();state.currentCallId=call.id;await pc.setRemoteDescription(new RTCSessionDescription(call.offer));state.remoteDescriptionSet=true;await addRemoteCandidates(call);const ans=await pc.createAnswer();await pc.setLocalDescription(ans);await update(voiceCallRef(),{answer:serDesc(pc.localDescription),status:'answered',answeredAt:Date.now()});state.voiceSignalReady=true;await flushIce();state.incomingCall=null;renderVoiceUi()}catch(e){console.error(e);cleanupVoice();toast('تعذر قبول المكالمة.')}finally{state.processingVoice=false}}
async function declineVoice(){const c=state.incomingCall;els.voiceIncomingModal.classList.add('hidden');state.incomingCall=null;if(c?.id)await update(voiceCallRef(),{status:'declined',endedAt:Date.now()}).catch(()=>{})}
async function handleVoiceSignal(call){if(state.processingVoice)return;if(!call){if(state.currentCallId||state.incomingCall)cleanupVoice(true);return}if(call.status==='ringing'&&call.calleeUid===state.uid&&!state.currentCallId){state.incomingCall=call;els.voiceCallerName.textContent=state.room?.players?.[call.callerUid]?.name||'صاحبك';els.voiceIncomingModal.classList.remove('hidden');return}if(call.status==='declined'&&call.callerUid===state.uid){toast('صاحبك رفض المكالمة.');cleanupVoice();return}if(call.status==='ended'){if(state.currentCallId)toast('تم إنهاء المكالمة.');cleanupVoice(true);return}if(state.currentCallId!==call.id||!state.peer)return;if(call.callerUid===state.uid&&call.answer&&!state.remoteDescriptionSet){await state.peer.setRemoteDescription(new RTCSessionDescription(call.answer)).catch(console.warn);state.remoteDescriptionSet=true}await addRemoteCandidates(call)}
function renderVoiceUi(){els.voiceCallBtn.disabled=!otherUid()||!!state.currentCallId;els.voiceCallLabel.textContent=state.currentCallId?'مشغول':'اتصال';els.voiceActiveBar.classList.toggle('hidden',!state.currentCallId);els.voiceMuteBtn.textContent=state.voiceMuted?'🎙️ تشغيل':'🔇 كتم'}
function toggleMute(){if(!state.localStream)return;state.voiceMuted=!state.voiceMuted;state.localStream.getAudioTracks().forEach(t=>t.enabled=!state.voiceMuted);renderVoiceUi()}
async function hangup(){if(state.roomCode&&state.currentCallId)await update(voiceCallRef(),{status:'ended',endedBy:state.uid,endedAt:Date.now()}).catch(()=>{});cleanupVoice()}
function cleanupVoice(hideIncoming=true){try{state.peer?.close()}catch{}state.peer=null;state.localStream?.getTracks().forEach(t=>t.stop());state.localStream=null;state.remoteStream?.getTracks().forEach(t=>t.stop());state.remoteStream=null;els.remoteAudio.srcObject=null;state.currentCallId=null;state.voiceSignalReady=false;state.pendingIce=[];state.seenIce=new Set();state.remoteDescriptionSet=false;state.voiceMuted=false;if(hideIncoming){state.incomingCall=null;els.voiceIncomingModal.classList.add('hidden')}renderVoiceUi()}

// ---------------- Utilities ----------------
function playSound(type){if(!state.sound)return;const map={move:'./assets/chess-move.wav?v=7.3.0',capture:'./assets/chess-capture.wav?v=7.3.0',castle:'./assets/chess-castle.wav?v=7.3.0',check:'./assets/chess-check.wav?v=7.3.0'};const src=map[type]||map.move;try{const audio=(state.audio[type]||state.audio.move)?.cloneNode?.()||new Audio(src);audio.volume=type==='check'?0.62:0.55;audio.currentTime=0;audio.play().catch(()=>{});}catch{}}
async function shareRoom(){const url=new URL('./chess.html',location.href);url.searchParams.set('room',state.roomCode);const text=`تعالى نلعب شطرنج على القهوة — كود الغرفة ${state.roomCode}`;if(navigator.share){try{await navigator.share({title:'القهوة — شطرنج',text,url:url.href});return}catch{}}await navigator.clipboard.writeText(url.href);toast('تم نسخ رابط المباراة.')}
async function copyCode(){await navigator.clipboard.writeText(state.roomCode);toast('تم نسخ الكود.')}
function leaveLocal(){state.roomUnsub?.();state.roomUnsub=null;cleanupVoice();state.roomCode=null;state.room=null;state.reviewFen=null;localStorage.removeItem('chess_room');location.href='./'}
async function downloadPgn(){if(!state.room)return;const blob=new Blob([pgnText(state.room)],{type:'application/x-chess-pgn;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`alqahwa-${state.roomCode||'chess'}.pgn`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}

// ---------------- Events ----------------
els.avatarPicker.addEventListener('click',e=>{const b=e.target.closest('button[data-avatar]');if(!b)return;state.selectedAvatar=b.dataset.avatar;els.avatarPicker.querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b))});
els.createRoomBtn.addEventListener('click',createRoom);els.showJoinBtn.addEventListener('click',()=>els.joinBox.classList.toggle('hidden'));els.joinRoomBtn.addEventListener('click',()=>joinRoom(els.roomCodeInput.value));els.roomCodeInput.addEventListener('keydown',e=>e.key==='Enter'&&joinRoom(els.roomCodeInput.value));els.copyCodeBtn.addEventListener('click',copyCode);els.shareRoomBtn.addEventListener('click',shareRoom);els.shareInGameBtn.addEventListener('click',shareRoom);els.leaveLobbyBtn.addEventListener('click',leaveLocal);els.offerDrawBtn.addEventListener('click',offerDraw);els.acceptDrawBtn.addEventListener('click',acceptDraw);els.declineDrawBtn.addEventListener('click',declineDraw);els.resignBtn.addEventListener('click',resign);els.rematchBtn.addEventListener('click',rematch);els.resultHomeBtn.addEventListener('click',leaveLocal);els.livePositionBtn.addEventListener('click',()=>{state.reviewFen=null;renderGame(state.room)});els.downloadPgnBtn.addEventListener('click',downloadPgn);els.soundBtn.addEventListener('click',()=>{state.sound=!state.sound;localStorage.setItem('chess_sound',state.sound?'1':'0');els.soundBtn.textContent=state.sound?'🔊':'🔇'});
els.chessBoard.addEventListener('click',e=>{if(state.drag)return;const sq=e.target.closest('.square');if(sq)chooseSquare(Number(sq.dataset.index))});
els.chessBoard.addEventListener('pointerdown',e=>{const p=e.target.closest('.piece.draggable');if(p)startDrag(e,p)});window.addEventListener('pointermove',e=>{if(state.drag){positionGhost(e);e.preventDefault()}});window.addEventListener('pointerup',e=>{if(state.drag)endDrag(e)});
els.promotionChoices.addEventListener('click',e=>{const b=e.target.closest('button[data-piece]');if(!b||!state.pendingPromotion)return;const m=state.pendingPromotion.moves.find(x=>x.promotion===b.dataset.piece);state.pendingPromotion=null;els.promotionModal.classList.add('hidden');if(m)submitMove(m)});
els.chatToggleBtn.addEventListener('click',()=>{els.chatPanel.classList.toggle('hidden');els.chatUnread.classList.add('hidden');requestAnimationFrame(()=>els.chatMessages.scrollTop=els.chatMessages.scrollHeight)});els.chatCloseBtn.addEventListener('click',()=>els.chatPanel.classList.add('hidden'));els.chatForm.addEventListener('submit',e=>{e.preventDefault();sendChat(els.chatInput.value)});els.reactions.addEventListener('click',e=>{const b=e.target.closest('button');if(b)sendReaction(b.textContent.trim())});els.voiceCallBtn.addEventListener('click',startVoice);els.voiceAcceptBtn.addEventListener('click',acceptVoice);els.voiceDeclineBtn.addEventListener('click',declineVoice);els.voiceMuteBtn.addEventListener('click',toggleMute);els.voiceHangupBtn.addEventListener('click',hangup);

setInterval(()=>{if(state.room?.game&&els.gameView.classList.contains('active'))renderClocks(state.room)},100);

els.boardThemeChoice?.addEventListener('change',()=>setVisualTheme('board',els.boardThemeChoice.value));
els.gameBoardThemeChoice?.addEventListener('change',()=>setVisualTheme('board',els.gameBoardThemeChoice.value));
els.pieceThemeChoice?.addEventListener('change',()=>setVisualTheme('piece',els.pieceThemeChoice.value));
els.gamePieceThemeChoice?.addEventListener('change',()=>setVisualTheme('piece',els.gamePieceThemeChoice.value));

(async function boot(){state.sound=localStorage.getItem('chess_sound')!=='0';els.soundBtn.textContent=state.sound?'🔊':'🔇';const n=localStorage.getItem('coffee_name');if(n)els.playerName.value=n;const a=localStorage.getItem('coffee_avatar')||'😎';state.selectedAvatar=a;els.avatarPicker.querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x.dataset.avatar===a));els.timeControl.value=localStorage.getItem('chess_time')||'0';els.colorChoice.value=localStorage.getItem('chess_color')||'random';els.boardThemeChoice.value=localStorage.getItem('chess_board_theme')||'classic';els.pieceThemeChoice.value=normalizePieceTheme(localStorage.getItem('chess_piece_theme')||'classic');syncThemeControls();applyVisualThemes();renderPromotionChoices('w');renderMiniBoard();preloadSound('move','./assets/chess-move.wav?v=7.3.0');preloadSound('capture','./assets/chess-capture.wav?v=7.3.0');preloadSound('castle','./assets/chess-castle.wav?v=7.3.0');preloadSound('check','./assets/chess-check.wav?v=7.3.0');if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js?v=7.3.0').catch(console.warn);try{await ensureAuth();onValue(ref(db,'.info/serverTimeOffset'),snap=>{state.serverOffset=Number(snap.val()||0)});const urlRoom=new URL(location.href).searchParams.get('room'),saved=localStorage.getItem('chess_room'),candidate=urlRoom||saved;if(candidate&&/^\d{6}$/.test(candidate)){
  const snap=await get(roomRef(candidate));
  if(snap.exists()){
    const r=snap.val();
    if((r.gameType||'domino')!=='chess'){
      els.homeMessage.textContent='الكود ده خاص بلعبة دومينو.'
    }else{
      const mine=[r.hostUid,r.guestUid].includes(state.uid);
      if(mine) await enterRoom(candidate);
      else if(urlRoom){
        els.roomCodeInput.value=candidate;els.joinBox.classList.remove('hidden');
        if(!r.guestUid){
          if((els.playerName.value||'').trim()) await joinRoom(candidate);
          else els.homeMessage.textContent='اكتب اسمك ثم اضغط دخول للانضمام للمباراة.';
        }else els.homeMessage.textContent='غرفة الشطرنج مكتملة بالفعل.';
      }
    }
  }else if(urlRoom){
    els.roomCodeInput.value=candidate;els.joinBox.classList.remove('hidden');
    els.homeMessage.textContent='الغرفة انتهت أو الكود غير موجود.';
  }
}}catch(e){console.error(e);els.homeMessage.textContent='تعذر الاتصال بـ Firebase.'}})();
